  async function buscarTodosRegistros({tabela,colunas="*",filtros=[],ordem="id",tamanhoPagina=1000}){const resultado=[];for(let inicio=0;;inicio+=tamanhoPagina){let q=db().from(tabela).select(colunas).order(ordem,{ascending:true}).range(inicio,inicio+tamanhoPagina-1);for(const f of filtros)q=q[f.operador](f.coluna,f.valor);const{data,error:e}=await q;if(e)throw e;const lote=data||[];resultado.push(...lote);if(lote.length<tamanhoPagina)break;}return resultado;}
