  function inicioPeriodo(ano,mes){return `${ano}-${String(mes).padStart(2,"0")}-01`;}
  function inicioProximoPeriodo(ano,mes){const data=new Date(Date.UTC(Number(ano),Number(mes),1));return `${data.getUTCFullYear()}-${String(data.getUTCMonth()+1).padStart(2,"0")}-01`;}
