  async function carregarCatalogoPeriodosCompleto(){const colunasCatalogo="importacao_id,ano,mes,nome_arquivo,status,ativa,concluido_em,criado_em",colunasImportacoes="id,ano,mes,nome_arquivo,status,ativa,periodos,concluido_em,criado_em";const[respostaCatalogo,respostaImportacoes,operacoes]=await Promise.all([db().from("v_catalogo_periodos").select(colunasCatalogo),db().from("importacoes").select(colunasImportacoes).in("status",["concluida","concluida_com_avisos"]),buscarTodosRegistros({tabela:"operacoes",colunas:"id,importacao_id,data_operacao",ordem:"id",tamanhoPagina:1000})]);if(respostaCatalogo.error)throw respostaCatalogo.error;if(respostaImportacoes.error)throw respostaImportacoes.error;const importacoes=respostaImportacoes.data||[],porId=new Map(importacoes.map(item=>[item.id,item])),mapa=new Map(),fontes={catalogo:[],importacoes:[],operacoes:[]};const registrar=(item,origem,substituir=false)=>{if(!item?.importacao_id||!periodoValido(item.ano,item.mes))return;const chave=chavePeriodo(item.ano,item.mes),registro={...item,ano:Number(item.ano),mes:Number(item.mes),periodo:chave,origem};if(substituir||!mapa.has(chave))mapa.set(chave,registro);fontes[origem].push(registro);};(respostaCatalogo.data||[]).forEach(item=>registrar(item,"catalogo",true));importacoes.forEach(importacao=>{const declarados=Array.isArray(importacao.periodos)?[...importacao.periodos]:[];if(periodoValido(importacao.ano,importacao.mes))declarados.push({ano:importacao.ano,mes:importacao.mes});declarados.forEach(valor=>{const periodo=periodoDoValor(valor);if(periodo)registrar({importacao_id:importacao.id,...periodo,nome_arquivo:importacao.nome_arquivo,status:importacao.status,ativa:importacao.ativa,concluido_em:importacao.concluido_em,criado_em:importacao.criado_em},"importacoes");});});const ultimaOperacao=new Map();operacoes.forEach(item=>{const data=dataIso(item.data_operacao),match=data.match(/^(\d{4})-(\d{2})/);if(!match||!item.importacao_id)return;const chave=chavePeriodo(match[1],match[2]),anterior=ultimaOperacao.get(chave);if(!anterior||numero(item.id)>numero(anterior.id))ultimaOperacao.set(chave,item);});ultimaOperacao.forEach((operacao,chave)=>{const[ano,mes]=chave.split("-").map(Number),meta=porId.get(operacao.importacao_id)||{};registrar({importacao_id:operacao.importacao_id,ano,mes,nome_arquivo:meta.nome_arquivo||"Importação com operações",status:meta.status||"operacoes_importadas",ativa:Boolean(meta.ativa),concluido_em:meta.concluido_em||null,criado_em:meta.criado_em||null},"operacoes");});const catalogo=[...mapa.values()].sort((a,b)=>Number(a.ano)-Number(b.ano)||Number(a.mes)-Number(b.mes));console.groupCollapsed("[CCO Diagnóstico] catálogo completo");console.table(fontes.catalogo);console.table(fontes.importacoes);console.table(fontes.operacoes);console.table(catalogo.map(item=>({ano:item.ano,mes:item.mes,importacao_id:item.importacao_id,origem:item.origem,status:item.status,ativa:item.ativa})));console.groupEnd();return catalogo;}
  async function carregarCatalogoPeriodosCCO(){return window.CCOPainelService.getCatalogoPeriodos();}
  async function inicializarPeriodosCCO(){const controle=window.CCO_PERIODOS;if(controle.inicializado)return controle.catalogo;if(controle.inicializando)return controle.inicializando;controle.inicializando=carregarCatalogoPeriodosCCO().then(catalogo=>{controle.catalogo=catalogo;controle.inicializado=true;estado.catalogo=catalogo;window.CCO_CACHE=window.CCO_CACHE||{};window.CCO_CACHE.catalogo=[...catalogo];window.__CCO_CATALOGO_PERIODOS__=[...catalogo];window.__CCO_PERIODOS_REAIS_V12__=[...catalogo].sort((a,b)=>b.ano-a.ano||b.mes-a.mes);window.__CCO_IMPORTACOES_POR_PERIODO__=Object.fromEntries(catalogo.map(item=>[item.periodo,item]));return catalogo;}).finally(()=>{controle.inicializando=null;});return controle.inicializando;}
  function preencherAnosCCO(catalogo){const selectAno=seletor("filtroAno"),valorAnterior=Number(selectAno?.value),anos=[...new Set((catalogo||[]).map(item=>Number(item.ano)).filter(Number.isFinite))].sort((a,b)=>b-a);if(!selectAno)return anos;selectAno.replaceChildren();anos.forEach(ano=>{const option=document.createElement("option");option.value=String(ano);option.textContent=String(ano);selectAno.appendChild(option);});if(anos.includes(valorAnterior))selectAno.value=String(valorAnterior);return anos;}
