  async function carregarPainel(){const token=++estado.token;limparEstadoPeriodo();atualizarStatus("Carregando dados da base...");try{const ano=Number(seletor("filtroAno")?.value),mes=Number(seletor("filtroMes")?.value);const imp=await obterImportacaoPeriodo(ano,mes);if(!imp){estado.importacao={ano,mes,importacao_id:null};montarFiltros();atualizarStatus(`Sem dados importados para ${String(mes).padStart(2,"0")}/${ano}.`);renderizar();return;}const fontes=await carregarFontes(imp);if(token!==estado.token)return;estado.importacao=imp;estado.operacoes=fontes.operacoes;estado.operacoesDias=fontes.operacoesDias;estado.executivo=fontes.executivo;estado.dias=[];estado.diasP9Raw=numero(fontes.diasP9Raw);estado.datasP9Raw=fontes.datasP9Raw||[];montarFiltros();atualizarStatus(`Banco carregado: ${String(imp.mes).padStart(2,"0")}/${imp.ano} • resumo executivo`);renderizar();}catch(e){if(token!==estado.token)return;erro("carregar painel",e);atualizarStatus(`Erro ao carregar o painel: ${e.message||e}`);}}
