  function diagnosticarCamadas(ops,dados){const contar=lista=>Object.fromEntries(ORDEM_SERVICOS_CCO.map(servico=>[servico,lista.filter(item=>obterServicoItem(item)===servico).length]));const operacoes=contar(ops),painel=contar(estado.executivo),renderizados=new Set(dados.map(obterServicoItem));console.groupCollapsed(`[CCO Diagnóstico] camadas ${String(estado.importacao?.mes||"").padStart(2,"0")}/${estado.importacao?.ano||"—"}`);console.table(ORDEM_SERVICOS_CCO.map(servico=>({servico,operacoes:operacoes[servico],painel_executivo:painel[servico],renderizado:renderizados.has(servico)?"sim":"não",desaparece_em:operacoes[servico]||painel[servico]?renderizados.has(servico)?"—":"consolidação/renderização":"origem"})));console.groupEnd();}
  function limparCachePeriodos(){estado.cache.clear();window.CCOCache?.invalidar?.("painel");window.CCO_CACHE=window.CCO_CACHE||{};window.CCO_CACHE.catalogo=[];window.CCO_CACHE.dadosPeriodo=null;window.CCO_CACHE.linhasConsolidadas=null;window.CCO_CACHE.importacaoAtual=null;window.__CCO_IMPORTACOES_POR_PERIODO__={};window.__CCO_IMPORTACAO_ATIVA__=null;delete window.__CCO_CATALOGO_PERIODOS__;window.CCO_PERIODOS.catalogo=[];window.CCO_PERIODOS.inicializado=false;window.CCO_PERIODOS.inicializando=null;}
  async function recarregarCatalogoPainelGeral(){const anterior=window.__CCO_PERIODO_ATUAL__;limparCachePeriodos();const catalogo=await inicializarPeriodosCCO();await montarFiltrosPeriodosCCO(catalogo,anterior);await carregarPainel();return catalogo;}
  async function iniciarInterno(){try{db();seletor("filtroDia")?.addEventListener("change",renderizar);return await iniciarFiltrosPeriodosCCO();}catch(e){erro("inicialização",e);const nome=seletor("nomeArquivo");if(nome)nome.textContent=e.message||String(e);return[];}}
